// Pick next 5 searches (pool x title x city) that are not yet in the "queries" tab
const PER_RUN = 15;
const CITIES = ["Bengaluru","Hyderabad","Pune","Chennai","Noida","Gurugram","Mumbai","Delhi","Kolkata","Ahmedabad","Kochi","Indore","Jaipur","Chandigarh","Coimbatore","Thiruvananthapuram","Nagpur","Bhubaneswar","Mysuru","Vadodara"];
const SN = ["ServiceNow Developer","ServiceNow Administrator","ServiceNow Architect","ServiceNow Consultant","ServiceNow Technical Lead","ServiceNow ITSM Developer","ServiceNow ITOM","ServiceNow HRSD","ServiceNow CSM","ServiceNow SecOps","ServiceNow Business Analyst","ServiceNow Tester"];
const AI = ["Machine Learning Engineer","GenAI Engineer","LLM Engineer","AI Engineer","Data Scientist","Computer Vision Engineer","NLP Engineer","MLOps Engineer","AI Architect","Applied Scientist","Deep Learning Engineer","AI/ML Engineer"];

const key = (p, t, c) => `${p}|${t}|${c}`.toLowerCase();
const done1 = new Set(), done2 = new Set();
for (const it of $input.all()) {
  const r = it.json || {};
  if (!r.pool) continue;
  const k = key(r.pool, r.title, r.city);
  if (String(r.note || '').toLowerCase().includes('page 2')) done2.add(k); else done1.add(k);
}
const all = [];
for (const city of CITIES) for (let i = 0; i < 12; i++) {
  all.push({ pool: 'ServiceNow', title: SN[i], city });
  all.push({ pool: 'AI/ML', title: AI[i], city });
}
let pages = 1;
let picked = all.filter(q => !done1.has(key(q.pool, q.title, q.city))).slice(0, PER_RUN);
if (!picked.length) {
  pages = 2;
  picked = all.filter(q => !done2.has(key(q.pool, q.title, q.city))).slice(0, PER_RUN);
}
if (!picked.length) return [];   // sab ho gaya
for (const q of picked) q.query = `site:linkedin.com/in "${q.title}" "${q.city}"`;
return [{ json: { picked, pages, queryText: picked.map(q => q.query).join('\n') } }];

// Google results -> clean candidate rows (same 40 columns as the Claude flow)
const pick = $('Pick 5 searches').first().json;
const pages = $('Apify Google search').all().map(i => i.json);
const existing = new Set();
for (const n of ['Read ServiceNow URLs', 'Read AI_ML URLs'])
  for (const it of $(n).all()) if (it.json.linkedin_url) existing.add(String(it.json.linkedin_url).toLowerCase());

const now = new Date(Date.now() + 5.5 * 3600e3);           // IST
const today = now.toISOString().slice(0, 10);
const stamp = now.toISOString().slice(0, 16).replace('T', ' ');

const STATE = { bengaluru: 'Karnataka', bangalore: 'Karnataka', mysuru: 'Karnataka', mysore: 'Karnataka', hyderabad: 'Telangana', secunderabad: 'Telangana',
  pune: 'Maharashtra', mumbai: 'Maharashtra', 'navi mumbai': 'Maharashtra', thane: 'Maharashtra', nagpur: 'Maharashtra', 'pimpri': 'Maharashtra',
  chennai: 'Tamil Nadu', coimbatore: 'Tamil Nadu', noida: 'Uttar Pradesh', 'greater noida': 'Uttar Pradesh', lucknow: 'Uttar Pradesh',
  gurugram: 'Haryana', gurgaon: 'Haryana', delhi: 'Delhi', 'new delhi': 'Delhi', kolkata: 'West Bengal', ahmedabad: 'Gujarat', vadodara: 'Gujarat',
  kochi: 'Kerala', cochin: 'Kerala', thiruvananthapuram: 'Kerala', trivandrum: 'Kerala', indore: 'Madhya Pradesh', bhopal: 'Madhya Pradesh',
  jaipur: 'Rajasthan', chandigarh: 'Chandigarh', mohali: 'Punjab', bhubaneswar: 'Odisha' };
const CITY_NAME = { bangalore: 'Bengaluru', gurgaon: 'Gurugram', cochin: 'Kochi', trivandrum: 'Thiruvananthapuram', mysore: 'Mysuru', 'new delhi': 'Delhi', pimpri: 'Pune' };
const POOL_RX = { 'ServiceNow': /service\s?now|\bsnow\b|\bitsm\b|\bitom\b|\bcmdb\b|\bhrsd\b/i,
  'AI/ML': /machine learning|\bml\b|\bai\b|artificial intelligence|gen\s?ai|generative|\bllms?\b|data scien|computer vision|\bnlp\b|deep learning|mlops|\bagentic\b|applied scientist|research scientist/i };
const REJECT_RX = /recruit|talent acquisition|\bhr\b|human resource|staffing|sourcing specialist|\bsales\b|business development|account (manager|executive)/i;
const STD = { 'ServiceNow Developer': 'ServiceNow Developer', 'ServiceNow ITSM Developer': 'ServiceNow Developer', 'ServiceNow Administrator': 'ServiceNow Administrator',
  'ServiceNow Architect': 'ServiceNow Architect', 'ServiceNow Consultant': 'ServiceNow Consultant', 'ServiceNow Technical Lead': 'ServiceNow Technical Lead',
  'ServiceNow ITOM': 'ServiceNow Developer', 'ServiceNow HRSD': 'ServiceNow Developer', 'ServiceNow CSM': 'ServiceNow Developer', 'ServiceNow SecOps': 'ServiceNow Developer',
  'ServiceNow Business Analyst': 'ServiceNow Business Analyst', 'ServiceNow Tester': 'ServiceNow Tester',
  'Machine Learning Engineer': 'Machine Learning Engineer', 'AI/ML Engineer': 'Machine Learning Engineer', 'Deep Learning Engineer': 'Machine Learning Engineer',
  'GenAI Engineer': 'Generative AI / LLM Engineer', 'LLM Engineer': 'Generative AI / LLM Engineer', 'AI Engineer': 'AI Engineer', 'Data Scientist': 'Data Scientist',
  'Computer Vision Engineer': 'Computer Vision Engineer', 'NLP Engineer': 'NLP Engineer', 'MLOps Engineer': 'MLOps Engineer', 'AI Architect': 'AI Architect',
  'Applied Scientist': 'Applied / Research Scientist' };
const ROLE_SN = [[/architect/i, 'Architect'], [/admin/i, 'Administrator'], [/consult/i, 'Consultant'], [/test|\bqa\b/i, 'Tester'], [/business analyst|\bba\b/i, 'BA'], [/lead|manager/i, 'Lead'], [/./, 'Developer']];
const ROLE_AI = [[/gen\s?ai|generative|llm|agentic/i, 'GenAI'], [/vision/i, 'Computer Vision'], [/nlp|language/i, 'NLP'], [/mlops/i, 'MLOps'], [/data scien/i, 'Data Science'], [/research|applied scien/i, 'Research'], [/./, 'ML Engineering']];
const MOD_SN = [['ITSM', /\bitsm\b|incident|change management|service catalog/i], ['ITOM', /\bitom\b|discovery|event management/i], ['CMDB', /\bcmdb\b/i], ['HRSD', /\bhrsd\b|\bhr service/i],
  ['CSM', /\bcsm\b|customer service management/i], ['SecOps', /secops|security operations/i], ['ITAM/SAM', /\bitam\b|\bsam\b|asset management/i], ['GRC/IRM', /\bgrc\b|\birm\b/i],
  ['ITBM/SPM', /\bitbm\b|\bspm\b|\bppm\b/i], ['Service Portal', /service portal/i], ['Integrations', /integration|rest api/i], ['Flow Designer', /flow designer/i]];
const MOD_AI = [['GenAI', /gen\s?ai|generative/i], ['LLMs', /\bllms?\b|large language/i], ['RAG', /\brag\b|retrieval/i], ['Agentic AI', /agentic|ai agents?|multi-agent/i],
  ['Computer Vision', /computer vision|\bcv\b|image|yolo|opencv/i], ['NLP', /\bnlp\b|natural language/i], ['MLOps', /mlops/i], ['Data Science', /data scien/i], ['Deep Learning', /deep learning|pytorch|tensorflow/i]];
const CERT_RX = /\b(CSA|CAD|CTA|CIS[- ]?[A-Z]{2,5}|CMA|ITIL(?: v4)?|AWS Certified[\w ]*|Azure AI[\w ]*|Google Cloud Certified[\w ]*|TensorFlow Developer)\b/g;

const clean = s => String(s || '').replace(/\s+/g, ' ').replace(/\s*\.\.\.$/, '').trim();
const slugOf = url => { const m = String(url || '').match(/linkedin\.com\/in\/([^/?#]+)/i); return m ? decodeURIComponent(m[1]).toLowerCase() : null; };
const findCity = text => {
  const t = String(text || '').toLowerCase();
  for (const c of Object.keys(STATE).sort((a, b) => b.length - a.length)) if (new RegExp(`\\b${c}\\b`).test(t)) return c;
  return null;
};
const cap = c => CITY_NAME[c] || c.replace(/\b\w/g, x => x.toUpperCase());

const rows = [], perQuery = {}, rejected = { not_india: 0, wrong_title: 0, recruiter: 0, no_name: 0, duplicate: 0 };
let googleResults = 0, profiles = 0;
const seen = new Set();
for (const page of pages) {
  const term = (page.searchQuery && page.searchQuery.term) || '';
  const q = pick.picked.find(p => p.query === term) || pick.picked.find(p => term.includes(p.title) && term.includes(p.city));
  if (!q) continue;
  const qk = `${q.pool}|${q.title}|${q.city}`;
  perQuery[qk] = perQuery[qk] || { results: 0, added: 0 };
  for (const r of page.organicResults || []) {
    googleResults++; perQuery[qk].results++;
    const slug = slugOf(r.url);
    if (!slug) continue;
    profiles++;
    const url = `https://www.linkedin.com/in/${slug}`;
    if (seen.has(url) || existing.has(url) || existing.has(`https://www.linkedin.com/in/${slug}`)) { rejected.duplicate++; continue; }
    const pi = r.personalInfo || {};
    const parts = clean(r.title).replace(/\s*[|·-]\s*LinkedIn.*$/i, '').split(/\s+-\s+/);
    const name = clean(parts[0]);
    const headline = clean(parts.slice(1).join(' - '));
    const desc = clean(r.description);
    const blob = `${headline} ${pi.jobTitle || ''} ${desc}`;
    if (!name || name.length < 2 || /servicenow|linkedin|developer|engineer/i.test(name)) { rejected.no_name++; continue; }
    const loc = `${pi.location || ''} ${desc}`;
    const cityKey = findCity(pi.location) || findCity(desc) || (/\bindia\b/i.test(loc) ? q.city.toLowerCase() : null);
    if (!cityKey) { rejected.not_india++; continue; }
    if (REJECT_RX.test(`${headline} ${pi.jobTitle || ''}`)) { rejected.recruiter++; continue; }
    if (!POOL_RX[q.pool].test(blob)) { rejected.wrong_title++; continue; }
    seen.add(url);

    const titleText = `${headline} ${pi.jobTitle || ''}`;
    const exact = new RegExp(q.title.replace(/[/]/g, '.').replace(/\s+/g, '\\s*'), 'i').test(titleText) ||
      (q.pool === 'ServiceNow' && /service\s?now/i.test(titleText)) ||
      (q.pool === 'AI/ML' && POOL_RX['AI/ML'].test(titleText));
    // kul experience sirf tab jab likha ho ("6+ years", "5 years of experience"); "Present 2 years 10 months" = abhi ki job ka time
    const tm = blob.match(/(?:with\s+|over\s+)?(\d{1,2})\+\s*(?:years|yrs)|(\d{1,2})\s*(?:years|yrs)\s*(?:of\s*)?(?:experience|exp)/i);
    const y = tm ? Number(tm[1] || tm[2]) : '';
    const ten = blob.match(/Present\s*(\d{1,2})\s*years?(?:\s*(\d{1,2})\s*months?)?/i);
    const domain = ten && POOL_RX[q.pool].test(`${pi.jobTitle || ''} ${headline}`) ? Math.round((Number(ten[1]) + Number(ten[2] || 0) / 12) * 10) / 10 : '';
    const by = domain !== '' ? domain : y;
    const bucket = by === '' ? 'Unknown' : by < 2 ? '0-2' : by < 5 ? '2-5' : by < 8 ? '5-8' : '8+';
    const otw = /open\s?to\s?work|immediate joiner|#?immediatejoiner|seeking|looking for (a )?(new )?(job|opportunit|role)/i.test(blob);
    const sen = /\bintern\b/i.test(titleText) ? 'Intern' : /\b(head|director|manager)\b/i.test(titleText) ? 'Manager' :
      /\b(lead|principal|staff|architect)\b/i.test(titleText) ? 'Lead' : /\b(senior|sr\.?)\b/i.test(titleText) ? 'Senior' :
      /\b(junior|jr\.?|associate|trainee|fresher)\b/i.test(titleText) ? 'Junior' : 'Mid';
    const mods = (q.pool === 'ServiceNow' ? MOD_SN : MOD_AI).filter(([, rx]) => rx.test(blob)).map(([m]) => m);
    const certs = [...new Set((blob.match(CERT_RX) || []).map(c => c.toUpperCase().replace(/\s+/g, ' ')))];
    const edu = (desc.match(/Education:\s*([^·.]+)/i) || [])[1];
    const notes = [edu && `Education: ${clean(edu)}`, /immediate/i.test(blob) && 'Immediate joiner', (desc.match(/[A-Z][a-z]{2} \d{4} - Present/) || [])[0] && `Current role since ${(desc.match(/([A-Z][a-z]{2} \d{4}) - Present/) || [])[1]}`]
      .filter(Boolean).join('; ');
    const email = (desc.match(/[\w.+-]+@[\w-]+\.[\w.]+/) || [])[0] || '';
    const city = cap(cityKey);
    const row = {
      name, linkedin_url: url, headline, city,
      current_title: clean(pi.jobTitle) || headline, current_company: clean(pi.companyName),
      role_category: (q.pool === 'ServiceNow' ? ROLE_SN : ROLE_AI).find(([rx]) => rx.test(`${q.title} ${titleText}`))[1],
      total_experience_years: y, [q.pool === 'ServiceNow' ? 'servicenow_experience_years' : 'ai_ml_experience_years']: domain,
      experience_bucket: bucket, [q.pool === 'ServiceNow' ? 'modules' : 'specialization']: mods.join('; '),
      certifications: certs.join('; '), skills: '', open_to_work: otw ? 'Yes' : 'Unknown', resume_status: 'Not collected',
      standard_title: STD[q.title] || q.title, title_match: exact ? 'Exact' : 'Related', seniority: sen, past_employers: '',
      state: STATE[cityKey] || '', country: 'India', email, email_status: email ? 'Unverified' : 'Not found',
      phone: '', phone_status: 'Not found', contact_source: email ? 'Google snippet' : '', readiness: 'Discovered',
      interest: 'Unknown', availability: /immediate/i.test(blob) ? 'Immediate' : '', notice_period: '', expected_salary: '',
      consent: 'No', last_contacted: '', source: 'LinkedIn (Google search)', source_flow: 'n8n', search_query: `${q.title} / ${q.city}`,
      first_seen: today, last_updated: today, duplicate_flag: 'No', notes,
    };
    if (q.pool === 'AI/ML') row.github_url = '';
    rows.push({ json: { _tab: q.pool === 'ServiceNow' ? 'ServiceNow' : 'AI_ML', ...row } });
    perQuery[qk].added++;
  }
}
const totalRejected = Object.values(rejected).reduce((a, b) => a + b, 0);
const stats = {
  stamp, pages: pick.pages, googleResults, profiles, added: rows.length, rejected: totalRejected,
  rejectedNote: Object.entries(rejected).filter(([, v]) => v).map(([k, v]) => `${k} ${v}`).join(', ') || 'none',
  sn: rows.filter(r => r.json._tab === 'ServiceNow').length, ai: rows.filter(r => r.json._tab === 'AI_ML').length,
  perQuery: pick.picked.map(p => ({ ...p, ...(perQuery[`${p.pool}|${p.title}|${p.city}`] || { results: 0, added: 0 }) })),
};
if (!rows.length) return [{ json: { _tab: 'none', _stats: stats } }];
return rows.map((r, i) => (i === 0 ? { json: { ...r.json, _stats: stats } } : r));

// queries tab ke liye 5 rows (kaunsi search hui, kitne mile)
const s = $input.first().json._stats;
return s.perQuery.map(p => ({ json: { pool: p.pool, title: p.title, city: p.city, run_at: s.stamp, google_results: p.results,
  new_rows_added: p.added, note: (s.pages === 2 ? 'page 2; ' : '') + 'n8n' } }));

// runs tab ke liye 1 row
const s = $input.first().json._stats;
return [{ json: {
  'Run date': s.stamp, 'Flow': 'n8n (scheduled)', 'Queries': s.perQuery.length, 'Google results': s.googleResults,
  'LinkedIn profiles found': s.profiles, 'Rejected (not India / wrong title / duplicate)': s.rejected, 'New rows added': s.added,
  'Apify cost ($)': Math.round(s.perQuery.length * s.pages * 0.0045 * 1000) / 1000,
  'Notes': `${s.sn} ServiceNow + ${s.ai} AI/ML. Rejected: ${s.rejectedNote}.`,
} }];
